//! The wow-api declarations embedded in the compiler (decision T83), until
//! the package manager provides `wow-api-<flavor>` packages (milestone M6).
//! Generated by `cargo xtask types gen`; see `data/`.

/// A generated declaration file.
#[derive(Clone, Copy, Debug)]
pub struct File {
    pub path: &'static str,
    pub text: &'static str,
}

const SHARED: File = File {
    path: "<wow-api>/shared.d.wowlua",
    text: include_str!("../data/shared.d.wowlua"),
};

/// The declarations of a flavor: the shared file and the flavor's own.
pub fn declarations(flavor: &str) -> Option<[File; 2]> {
    let own = match flavor {
        "standard" => File {
            path: "<wow-api>/standard.d.wowlua",
            text: include_str!("../data/standard.d.wowlua"),
        },
        "camelot" => File {
            path: "<wow-api>/camelot.d.wowlua",
            text: include_str!("../data/camelot.d.wowlua"),
        },
        "mists" => File {
            path: "<wow-api>/mists.d.wowlua",
            text: include_str!("../data/mists.d.wowlua"),
        },
        "cata" => File {
            path: "<wow-api>/cata.d.wowlua",
            text: include_str!("../data/cata.d.wowlua"),
        },
        "wrath" => File {
            path: "<wow-api>/wrath.d.wowlua",
            text: include_str!("../data/wrath.d.wowlua"),
        },
        "tbc" => File {
            path: "<wow-api>/tbc.d.wowlua",
            text: include_str!("../data/tbc.d.wowlua"),
        },
        "vanilla" => File {
            path: "<wow-api>/vanilla.d.wowlua",
            text: include_str!("../data/vanilla.d.wowlua"),
        },
        _ => return None,
    };
    Some([SHARED, own])
}

/// The APIs a declaration file declares: global functions and globals
/// (`Name`), namespaces and their members (`Namespace.Member`).
pub fn declared_names(text: &str) -> std::collections::HashSet<String> {
    let mut out = std::collections::HashSet::new();
    let mut namespace: Option<String> = None;
    let ident = |s: &str| -> String {
        s.chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
            .collect()
    };
    for line in text.lines() {
        if let Some(rest) = line
            .strip_prefix("declare function ")
            .or_else(|| line.strip_prefix("@deprecated declare function "))
        {
            out.insert(ident(rest));
        } else if let Some(rest) = line.strip_prefix("declare global ") {
            out.insert(ident(rest));
        } else if let Some(rest) = line.strip_prefix("declare namespace ") {
            let ns = ident(rest);
            out.insert(ns.clone());
            namespace = Some(ns);
        } else if line == "end" {
            namespace = None;
        } else if let Some(ns) = &namespace
            && let Some(member) = line.strip_prefix("    ")
            && !member.starts_with(' ')
        {
            let member = member.strip_prefix("@deprecated ").unwrap_or(member);
            let member = member
                .strip_prefix("function ")
                .or_else(|| member.strip_prefix("namespace "))
                .or_else(|| member.strip_prefix("const "))
                .unwrap_or(member);
            let name = ident(member);
            if !name.is_empty() {
                out.insert(format!("{ns}.{name}"));
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    #[test]
    fn names() {
        let names = super::declared_names(
            "declare function GetTime(): number\ndeclare namespace C_X\n    function Do()\n    value: number\nend\ndeclare global UIParent: Frame\n",
        );
        for n in ["GetTime", "C_X", "C_X.Do", "C_X.value", "UIParent"] {
            assert!(names.contains(n), "{n}: {names:?}");
        }
        assert!(super::declarations("standard").is_some());
    }
}
